import{_ as e,o,c as d,a2 as r}from"./chunks/framework.a6FUKr6c.js";const u=JSON.parse('{"title":"Compared with Other Runtimes","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/comparison.md","filePath":"getting-started/comparison.md","lastUpdated":1794504758000}'),a={name:"getting-started/comparison.md"};function s(n,t,c,i,h,l){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="compared-with-other-runtimes" tabindex="-1">Compared with Other Runtimes <a class="header-anchor" href="#compared-with-other-runtimes" aria-label="Permalink to &quot;Compared with Other Runtimes&quot;">​</a></h1><p>Other tools also make agent runs durable. They differ in where the runs live and in how much of the agent-specific work (tool side effects, approvals, who may call which tool) they take off your hands. As of October 2026, going by each project&#39;s own docs:</p><table tabindex="0"><thead><tr><th></th><th>chamvi</th><th><a href="https://workflow-sdk.dev/docs/ai/human-in-the-loop" target="_blank" rel="noreferrer">Workflow DevKit</a> + <code>WorkflowAgent</code></th><th><a href="https://mastra.ai/docs/long-running-agents/durable-agents" target="_blank" rel="noreferrer">Mastra</a></th><th><a href="https://www.inngest.com/docs/self-hosting" target="_blank" rel="noreferrer">Inngest</a></th><th><a href="https://trigger.dev/docs/how-it-works" target="_blank" rel="noreferrer">Trigger.dev</a></th></tr></thead><tbody><tr><td><strong>Runs in</strong></td><td>Your Node process, one PostgreSQL database</td><td>Your process with the Postgres World (a reference implementation), or Vercel</td><td>Your process or a Mastra server, with a storage adapter</td><td>The Inngest server, which calls your app&#39;s endpoint</td><td>The Trigger.dev platform (cloud, or self-hosted with Postgres, Redis, ClickHouse and more)</td></tr><tr><td><strong>Checkpoint per LLM and tool step</strong></td><td>Yes</td><td>LLM calls; tools only when marked <code>&quot;use step&quot;</code></td><td>Durable agents (beta) resume from a snapshot, per step only when enabled</td><td>Yes, with <code>step.ai</code></td><td>No, a retry restarts the task; waits are snapshotted</td></tr><tr><td><strong>Tool side effects after a crash</strong></td><td>Recorded per effect key, <code>alreadyApplied</code> checks the remote system</td><td>Completed steps memoized; pass <code>stepId</code> to the API</td><td>May run twice, unless on the Inngest runner</td><td>Completed steps memoized; pass a stable key</td><td>Repeat in the parent task; child tasks deduped</td></tr><tr><td><strong>Approval that waits for days</strong></td><td><code>await approve(ctx, { title })</code> inside the tool, durable across restarts; approver needs <code>chamvi_agent_approve</code></td><td>Hook tokens, which are not credentials; your route authorizes</td><td>Resume by <code>runId</code> and <code>toolCallId</code></td><td><code>waitForEvent</code> with a timeout</td><td>Wait tokens</td></tr><tr><td><strong>Deduplicated intake</strong></td><td>Per agent, channel and caller, 7 days</td><td>A pattern you build with hooks</td><td>Not documented</td><td>Yes, 24 hours</td><td>Yes, 30 days by default</td></tr><tr><td><strong>One run at a time per key</strong></td><td><code>concurrencyKey</code></td><td>Not documented</td><td>Not documented</td><td><code>concurrency.key</code></td><td><code>concurrencyKey</code></td></tr><tr><td><strong>Cron across replicas</strong></td><td>Once per tick, overlap <code>skip</code>, <code>queue-one</code> or <code>allow</code></td><td>No cron</td><td>Yes, overlap not documented</td><td>Yes, overlap through concurrency settings</td><td>Yes, no skip-if-running policy</td></tr><tr><td><strong>Agents as an MCP server</strong></td><td><code>/mcp</code>, one <code>run_&lt;agent&gt;</code> tool per agent</td><td>No</td><td><code>MCPServer</code></td><td>No</td><td>No (its MCP server is developer tooling)</td></tr><tr><td><strong>Tools restricted per caller</strong></td><td><code>requireToolPermission()</code> reads the run&#39;s invoker</td><td>No</td><td>Tool-level checks are Enterprise</td><td>No</td><td>No</td></tr><tr><td><strong>License</strong></td><td>Apache-2.0</td><td>Apache-2.0</td><td>Apache-2.0, <code>ee/</code> source-available</td><td>Server SSPL (delayed Apache-2.0)</td><td>Apache-2.0</td></tr></tbody></table><p>Pick one of the others when you want what chamvi does not have yet: a hosted service, a hosted run dashboard, or Mastra&#39;s evals. Pick chamvi when the agent lives next to your app and its database, and when a webhook that fires twice must not post twice.</p>',4)])])}const g=e(a,[["render",s]]);export{u as __pageData,g as default};
